    private final Room deluxe = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));

    @Test
    void corporateDiscountDependsOnTheCompany() {
        Price price = price(deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE,
                "TECNOSUL");

        assertEquals(new BigDecimal("779.80"), price.subtotal());
        assertEquals(new BigDecimal("93.58"), price.discount());
        assertEquals(new BigDecimal("686.22"), price.total());
        assertEquals(new BigDecimal("140.36"), price(deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12),
                RatePlan.CORPORATE, "AGROVALE").discount());
        assertEquals(new BigDecimal("194.95"), price(deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12),
                RatePlan.CORPORATE, "FARMAVIDA").discount());
    }

    @Test
    void weekendPackageIsAFixedPriceEvenInHighSeason() {
        Price march = price(deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), RatePlan.WEEKEND_PACKAGE);
        Price july = price(suite, LocalDate.of(2027, 7, 9), LocalDate.of(2027, 7, 11), RatePlan.WEEKEND_PACKAGE);
        Price standard = price(standardRoom, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14),
                RatePlan.WEEKEND_PACKAGE);

        assertEquals(2, march.nights());
        assertEquals(new BigDecimal("820.00"), march.subtotal());
        assertEquals(new BigDecimal("0.00"), march.discount());
        assertEquals(new BigDecimal("820.00"), march.total());
        assertEquals(new BigDecimal("1200.00"), july.total());
        assertEquals(new BigDecimal("520.00"), standard.total());
    }

    @Test
    void longStayTakes10PercentOffAndKeepsHighSeason() {
        Price price = price(standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), RatePlan.LONG_STAY);

        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());

        Price highSeason = price(standardRoom, LocalDate.of(2027, 2, 27), LocalDate.of(2027, 3, 6),
                RatePlan.LONG_STAY);
        // 2 nights of 299.88 + 5 nights of 249.90
        assertEquals(new BigDecimal("1849.26"), highSeason.subtotal());
        assertEquals(new BigDecimal("184.93"), highSeason.discount());
    }
}
