    private static NewReservation withCompany(String companyCode) {
        NewReservation base = stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE);
        return new NewReservation(base.roomNumber(), base.guest(), base.checkIn(), base.checkOut(), base.guests(),
                base.ratePlan(), companyCode);
    }

    @Test
    void corporateNeedsTheCodeOfACompanyWithAnAgreement() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(withCompany(null))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(withCompany("OUTRAEMPRESA"))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(withCompany("tecnosul"))));

        Reservation reservation = service.create(withCompany("TECNOSUL"));
        assertEquals(new BigDecimal("686.22"), reservation.price().total());
        service.confirm(reservation.id());
        assertEquals(new BigDecimal("686.22"), service.cancel(reservation.id()).refund());
    }

    @Test
    void weekendPackageOnlyFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));

        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
        service.confirm(reservation.id());
        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
    }

    @Test
    void longStayNeedsSevenNightsAndRefundsEverything() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-01", "2027-03-07", 2, RatePlan.LONG_STAY))));

        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(reservation.id());
        assertEquals(new BigDecimal("1574.37"), service.cancel(reservation.id()).refund());
    }
}
