    @Test
    void corporateReservationUsesTheCompanyCodeAndOthersIgnoreIt() throws Exception {
        String corporate = RESERVATION_JSON.replace("\"STANDARD\"", "\"CORPORATE\", \"companyCode\": \"AGROVALE\"");
        HttpResponse<String> created = post("/reservations", corporate);
        assertEquals(201, created.statusCode());
        assertEquals("CORPORATE", json.readTree(created.body()).get("ratePlan").asText());

        String ignored = RESERVATION_JSON.replace("\"2027-07-10\"", "\"2027-09-10\"")
                .replace("\"2027-07-12\"", "\"2027-09-12\"")
                .replace("\"STANDARD\"", "\"STANDARD\", \"companyCode\": \"AGROVALE\"");
        assertEquals(201, post("/reservations", ignored).statusCode());
    }

    @Test
    void refusesAReservationTheRatePlanDoesNotAllow() throws Exception {
        String withoutCode = RESERVATION_JSON.replace("\"STANDARD\"", "\"CORPORATE\"");
        HttpResponse<String> response = post("/reservations", withoutCode);

        assertEquals(400, response.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
    }
}
